mixin B {
  void greet() => print('B');
}

mixin C {
  void greet() => print('C');
}

class D extends A with B, C {
  @override
  void greet() {
    super.greet(); // Calls C (last mixin)
    print('D');
  }
}

D().greet();
// Output:
// C
// D

