// .then chain
Future<Profile> loadProfileChain(String id) {
  return api.user(id)
      .then((u) => api.profile(u.id))
      .then((p) => augment(p))
      .catchError((e, s) {
        log('loadProfile failed: $e');
        return Profile.empty();         // recovered value flows down
      });
}

// async/await — clearer for anything beyond two steps
Future<Profile> loadProfileAwait(String id) async {
  try {
    final user    = await api.user(id);
    final profile = await api.profile(user.id);
    return augment(profile);
  } catch (e, s) {
    log('loadProfile failed: $e');
    return Profile.empty();
  }
}

// ── Subtle: order of catchError matters ──
Future<int> trickyCatch() {
  return computeSomething()
      .then((v) => v + 1)             // throws if v is null
      .catchError((e) {
        return 0;                     // ✅ recovers and the next .then sees 0
      })
      .then((v) => v * 2);            // runs on success OR after recovery
}

// ── ❌ Anti-pattern: catchError attached to a future you then discard ──
Future<int> swallowed() {
  final f = computeSomething();
  f.catchError((_) => 0);             // ❌ the recovered future is thrown away
  return f;                            // caller still sees the original error
}
