// ── API service with Dio ───────────────────────────
class ApiService {
  late final Dio _dio;

  ApiService(String baseUrl) {
    _dio = Dio(BaseOptions(
      baseUrl: baseUrl,
      connectTimeout: const Duration(seconds: 10),
      receiveTimeout: const Duration(seconds: 30),
      headers: {'Content-Type': 'application/json'},
    ));

    _dio.interceptors.addAll([
      // Auth header interceptor
      InterceptorsWrapper(
        onRequest: (options, handler) {
          final token = TokenStorage.getToken();
          if (token != null) options.headers['Authorization'] = 'Bearer $token';
          handler.next(options);
        },
        onError: (error, handler) async {
          if (error.response?.statusCode == 401) {
            await refreshToken();
            return handler.resolve(await _retry(error.requestOptions));
          }
          handler.next(error);
        },
      ),
      LogInterceptor(requestBody: true, responseBody: true),
    ]);
  }

  Future<List<User>> getUsers({int page = 1}) async {
    final response = await _dio.get('/users', queryParameters: {'page': page});
    return (response.data as List)
        .map((e) => User.fromJson(e as Map<String, dynamic>))
        .toList();
  }

  Future<User> createUser(String name, String email) async {
    final response = await _dio.post('/users', data: {'name': name, 'email': email});
    return User.fromJson(response.data as Map<String, dynamic>);
  }

  Future<Response<dynamic>> _retry(RequestOptions options) =>
      _dio.fetch(options);
}

class ProductListCubit extends Cubit<ProductListState> {
  final ProductRepository _repo;
  static const _pageSize = 20;

  int _page = 1;
  bool _hasMore = true;
  bool _loading = false;

  ProductListCubit(this._repo) : super(const ProductListState());

  Future<void> loadMore() async {
    if (_loading || !_hasMore) return;
    _loading = true;

    try {
      final newItems = await _repo.getProducts(page: _page, limit: _pageSize);
      _hasMore = newItems.length == _pageSize;
      _page++;
      emit(state.copyWith(
        items: [...state.items, ...newItems],
        hasMore: _hasMore,
        isLoading: false,
      ));
    } catch (e) {
      emit(state.copyWith(error: e.toString(), isLoading: false));
    } finally {
      _loading = false;
    }
  }

  Future<void> refresh() async {
    _page = 1; _hasMore = true; _loading = false;
    emit(const ProductListState(isLoading: true));
    await loadMore();
  }
}

// ── Scroll detection widget ─────────────────────────
class InfiniteProductList extends StatefulWidget {
  const InfiniteProductList({super.key});
  @override State<InfiniteProductList> createState() => _State();
}

class _State extends State<InfiniteProductList> {
  final _scrollCtrl = ScrollController();

  @override
  void initState() {
    super.initState();
    context.read<ProductListCubit>().loadMore();
    _scrollCtrl.addListener(_onScroll);
  }

  void _onScroll() {
    final pos = _scrollCtrl.position;
    // Load more when 200px from bottom
    if (pos.pixels >= pos.maxScrollExtent - 200) {
      context.read<ProductListCubit>().loadMore();
    }
  }

  @override void dispose() { _scrollCtrl.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    return BlocBuilder<ProductListCubit, ProductListState>(
      builder: (context, state) => ListView.builder(
        controller: _scrollCtrl,
        itemCount: state.items.length + (state.hasMore ? 1 : 0),
        itemBuilder: (context, index) {
          if (index == state.items.length) {
            return const Center(child: CircularProgressIndicator()); // loading indicator
          }
          return ProductTile(product: state.items[index]);
        },
      ),
    );
  }
}

// ── Using Dio with interceptors ────────────
import 'package:dio/dio.dart';

class ApiClient {
  late final Dio dio;

  ApiClient() {
    dio = Dio(BaseOptions(
      baseUrl: 'https://api.example.com',
      connectTimeout: const Duration(seconds: 5),
      receiveTimeout: const Duration(seconds: 10),
    ));

    dio.interceptors.add(AuthInterceptor(dio));
    dio.interceptors.add(LoggingInterceptor());
    dio.interceptors.add(ErrorInterceptor());
  }
}

// ── Auth interceptor ───────────────────────
class AuthInterceptor extends Interceptor {
  AuthInterceptor(this._dio);
  final Dio _dio;

  @override
  void onRequest(
    RequestOptions options,
    RequestInterceptorHandler handler,
  ) async {
    // Add token to all requests
    final token = await getAuthToken();
    if (token != null) {
      options.headers['Authorization'] = 'Bearer $token';
    }

    // Continue with modified request
    handler.next(options);
  }

  @override
  void onError(
    DioException err,
    ErrorInterceptorHandler handler,
  ) async {
    // Refresh token on 401 — but only once per request
    final opts = err.requestOptions;
    if (err.response?.statusCode == 401 && opts.extra['retried'] != true) {
      try {
        await refreshToken();          // de-duplicated: one in-flight refresh for all callers
        opts.extra['retried'] = true;  // stops an invalid token from looping forever
        opts.headers['Authorization'] = 'Bearer ${await getAuthToken()}';
        return handler.resolve(await _dio.fetch(opts)); // same base options + interceptors
      } catch (e) {
        return handler.reject(err);
      }
    }

    handler.next(err);
  }
}

// ── Logging interceptor ────────────────────
class LoggingInterceptor extends Interceptor {
  @override
  void onRequest(RequestOptions options, RequestInterceptorHandler handler) {
    print('REQUEST[${options.method}] => ${options.path}');
    print('Headers: ${options.headers}');
    print('Data: ${options.data}');
    handler.next(options);
  }

  @override
  void onResponse(Response response, ResponseInterceptorHandler handler) {
    print('RESPONSE[${response.statusCode}] => ${response.requestOptions.path}');
    print('Data: ${response.data}');
    handler.next(response);
  }

  @override
  void onError(DioException err, ErrorInterceptorHandler handler) {
    print('ERROR[${err.response?.statusCode}] => ${err.requestOptions.path}');
    print('Message: ${err.message}');
    handler.next(err);
  }
}

