@DriftDatabase(tables: [Tasks])
class AppDb extends _$AppDb {
  AppDb(super.e);

  @override int get schemaVersion => 2;

  @override
  MigrationStrategy get migration => MigrationStrategy(
    onCreate: (m) => m.createAll(),
    onUpgrade: (m, from, to) async {
      if (from < 2) await m.addColumn(tasks, tasks.dueAt);
    },
  );

  // Reactive query — emits whenever the tasks table changes
  Stream<List<Task>> watchOpenTasks() =>
      (select(tasks)..where((t) => t.done.equals(false))).watch();

  // Type-safe insert
  Future<int> add(String title) =>
      into(tasks).insert(TasksCompanion.insert(title: title));

  // Update with named-arg builder
  Future<int> setDone(int id, bool done) =>
      (update(tasks)..where((t) => t.id.equals(id)))
          .write(TasksCompanion(done: Value(done)));
}

// Tables.dart
class Tasks extends Table {
  IntColumn  get id    => integer().autoIncrement()();
  TextColumn get title => text().withLength(min: 1, max: 200)();
  BoolColumn get done  => boolean().withDefault(const Constant(false))();
  DateTimeColumn get dueAt => dateTime().nullable()();
}

// Isar example (package: isar_community, the maintained v3 fork)
// Annotated model + indexed lookup
@collection
class Note {
  Id id = Isar.autoIncrement;

  @Index(caseSensitive: false)
  late String title;

  @Index(type: IndexType.value)
  late DateTime updatedAt;

  late String body;
}

// Bootstrap
final isar = await Isar.open(
  [NoteSchema],
  directory: (await getApplicationDocumentsDirectory()).path,
);

// Write inside a transaction
await isar.writeTxn(() async {
  await isar.notes.put(Note()
    ..title = 'Idea'
    ..body = 'spaced repetition mode'
    ..updatedAt = DateTime.now());
});

// Indexed lookup — fast even with millions of rows
final recent = await isar.notes
    .filter()
    .titleStartsWith('idea', caseSensitive: false)
    .sortByUpdatedAtDesc()
    .limit(20)
    .findAll();

// Reactive — UI auto-updates when collection changes
final stream = isar.notes
    .where()
    .sortByUpdatedAtDesc()
    .watch(fireImmediately: true);

// Pessimistic — wrap any multi-step write in a transaction
Future<void> markDone(Database db, int id) {
  return db.transaction((txn) async {
    final rows = await txn.query('tasks',
        where: 'id = ?', whereArgs: [id], limit: 1);
    if (rows.isEmpty) throw StateError('not found');
    if ((rows.first['done'] as int) == 1) return; // already done — no-op
    await txn.update('tasks', {'done': 1},
        where: 'id = ?', whereArgs: [id]);
    await txn.insert('audit', {'task_id': id, 'at': DateTime.now().millisecondsSinceEpoch});
  });
}

// Optimistic — version column avoids lost updates without long locks
Future<bool> editTitle(Database db, int id, String title, int expectedRev) async {
  final updated = await db.update(
    'tasks',
    {'title': title, 'rev': expectedRev + 1},
    where: 'id = ? AND rev = ?', whereArgs: [id, expectedRev],
  );
  return updated == 1; // false ⇒ someone else won — refetch and re-prompt
}

// Serialize background sync through a single mutex so it never interleaves
import 'package:synchronized/synchronized.dart';
final _syncLock = Lock();
Future<void> applyServerPatch(Database db, ServerPatch p) {
  return _syncLock.synchronized(() async {
    await db.transaction((txn) async {
      for (final op in p.ops) await op.apply(txn);
    });
  });
}

// Enable WAL once on open for better read/write concurrency
Future<Database> openWal(String path) async {
  final db = await openDatabase(path);
  await db.rawQuery('PRAGMA journal_mode=WAL');
  await db.rawQuery('PRAGMA synchronous=NORMAL'); // good default with WAL
  return db;
}

